  // 9 ─────────────────────────────────────────────────────────────
  mistakes: [
    { error: "Considérer le rail comme un simple support de plancher, qu'on peut égratigner ou servir de point d'appui.",
      why: "Le rail est une pièce de structure : il retient les sièges, y compris dans un choc. Une entaille y est un point de départ de fissure, et une déformation gêne l'engagement des ferrures.",
      better: "Le traiter comme une pièce structurale : jamais d'outil posé dessus, pas de traînage de matériel, et toute marque profonde est signalée comme une anomalie." },
    { error: "Forcer une ferrure qui ne veut pas glisser, au maillet ou à deux.",
      why: "Une ferrure qui bloque a une cause : tétons pas en face des ouvertures, objet dans la gorge, déformation. Forcer marque le rail, tord la ferrure ou casse un téton, c'est-à-dire abîme la pièce qui retient le passager.",
      better: "S'arrêter, ressortir la ferrure par les ouvertures, regarder la gorge à la lampe, puis recommencer ; et si le blocage revient, le signaler." },
    { error: "Déclarer un siège verrouillé parce qu'il « ne bouge plus à la main ».",
      why: "Une ferrure peut être calée dans le rail sans que le pion soit descendu. Au moindre effort réel (freinage), elle glisse et le siège part.",
      better: "Contrôler le verrouillage comme le prévoit la consigne du siège (témoin, pion, essai prévu), pas au jugé." },
    { error: "Poser une boîte de visserie ou un outil « juste une seconde » sur le rail ou sur le siège voisin.",
      why: "Dans une cabine, une seconde suffit pour qu'un outil tombe dans une gorge ; il disparaît à la vue et ne se retrouve plus.",
      better: "Garder un bac fermé hors de la zone, ne sortir que ce qui est utilisé, et poser l'outil à un endroit prévu pour qu'il ne roule pas." },
    { error: "Saisir un siège par un accoudoir, la tablette ou la barre de retenue pour le soulever.",
      why: "Ces pièces sont dimensionnées pour un usage passager, pas pour porter un siège de plusieurs dizaines de kilos. Elles se faussent, se cassent ou se détachent, et le siège tombe.",
      better: "Saisir l'armature et les pieds, à deux au minimum, et se faire guider si le siège cache la vue." },
    { error: "Retrouver la position d'une rangée en comptant les ouvertures du rail à l'œil.",
      why: "Les ouvertures donnent les positions possibles, pas celle qui est demandée. Une rangée mal placée peut gêner une issue, une cloison ou un monument.",
      better: "Prendre la position et le pas dans le dossier de configuration applicable, et vérifier en contrôlant ce qui a été fait." },
    { error: "Souffler à l'air comprimé dans la gorge du rail pour la nettoyer.",
      why: "Le souffle déplace les objets (copeaux, poussières, vis légères) plus loin dans le rail ou sous les panneaux : on les cache au lieu de les enlever.",
      better: "Aspirer, regarder à la lampe sous plusieurs angles, puis compter les objets qu'on a sortis." },
  ],

